    border: 1px solid #e5e7eb;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.entry-header h5,
.reference-form h5 {
    margin: 0;
    color: #374151;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
}

.character-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

.character-count.warning {
    color: #d97706;
    font-weight: 500;
}

/* Review Step */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 0.375rem;
